125	            // Forbidden (403)
126	            elseif ($e instanceof AccessDeniedHttpException) {
127	                \Illuminate\Support\Facades\Log::warning('Access denied', [
128	                    'path' => $request->path(),
129	                    'message' => $e->getMessage(),
130	                ]);
131	
132	                $response = response()->json([
133	                    'message' => $e->getMessage() ?: 'Access denied',
134	                ], 403);
135	            }
136	
137	            // Preserve explicit response exceptions (e.g. throttle 429)
138	            elseif ($e instanceof HttpResponseException) {
139	                $response = $e->getResponse();
140	            }
141	
142	            // Generic error handling
143	            else {
144	                $statusCode = 500;
145	                if ($e instanceof HttpException) {
146	                    $statusCode = $e->getStatusCode();
147	                }
148	
149	                // Log full exception for debugging even in production
150	                if ($statusCode >= 500) {
151	                    \Illuminate\Support\Facades\Log::error('API Error', [
152	                        'exception' => $e,
153	                        'status' => $statusCode,
154	                    ]);
155	                }
156	
157	                // Don't expose internal errors in production
158	                $message = config('app.debug')
159	                    ? $e->getMessage()
160	                    : 'An error occurred';
