3	namespace App\Http\Middleware;
4	
5	use Closure;
6	use Illuminate\Http\Request;
7	use Symfony\Component\HttpFoundation\Response;
8	
9	// V2: Cache-Control headers — public GET endpoints get 15min cache; authenticated requests get no-store. Varies on X-Site-Subdomain for multi-tenant safety.
10	class AddPublicCacheHeaders
11	{
12	    /**
13	     * Public GET paths that are safe to cache at the CDN/proxy layer.
14	     * Anything NOT in this list will not receive public Cache-Control headers.
15	     * This is an allowlist — add new public-cacheable paths explicitly.
16	     */
17	    private const CACHEABLE_PATH_PREFIXES = [
18	        'api/public/site-by-slug',
19	        'api/public/booking/config-by-slug',
20	        'api/public/booking/services-by-slug',
21	        'api/public/store/featured-products-by-slug',
22	        'api/public/shopify/storefront-config',
23	    ];
24	
25	    /**
26	     * Paths (or path prefixes) that must never be publicly cached because they
27	     * carry per-user tokens, affect subscription state, or expose invite details.
28	     * These receive Cache-Control: no-store even if they are otherwise GET/200.
29	     */
30	    private const NO_STORE_PATH_PREFIXES = [
31	        'api/public/unsubscribe/',
32	        'api/public/brand-affiliate-invites/',
33	    ];
34	
35	    public function handle(Request $request, Closure $next): Response
36	    {
37	        $response = $next($request);
38	
39	        // Never cache authenticated API responses.
40	        if ($request->headers->has('Authorization')) {
41	            $response->headers->set('Cache-Control', 'private, no-store, max-age=0');
42	            $response->headers->set('Pragma', 'no-cache');
43	            $this->mergeVary($response, ['Authorization', 'Cookie', 'Accept-Encoding']);
44	
45	            return $response;
46	        }
47	
48	        $path = $request->path();
49	
50	        // Tokenized / sensitive GET endpoints must never be publicly cached.
51	        foreach (self::NO_STORE_PATH_PREFIXES as $prefix) {
52	            if (str_starts_with($path, $prefix)) {
53	                $response->headers->set('Cache-Control', 'private, no-store, max-age=0');
54	                $response->headers->set('Pragma', 'no-cache');
55	
56	                return $response;
57	            }
58	        }
59	
60	        // Only cache successful GET requests to explicitly allow-listed public paths.
61	        if ($request->isMethod('GET') && $response->isSuccessful()) {
62	            foreach (self::CACHEABLE_PATH_PREFIXES as $prefix) {
63	                if (str_starts_with($path, $prefix)) {
64	                    $response->headers->set('Cache-Control', 'public, max-age=900, s-maxage=900'); // 15 min
65	                    // All *-by-slug routes resolve the tenant from the X-Site-Subdomain header,
66	                    // so CDN/proxies must vary their cache on it to avoid cross-tenant poisoning.
67	                    $this->mergeVary($response, ['X-Site-Subdomain', 'Accept-Encoding']);
68	                    if (! $response->headers->has('X-Cache-Status')) {
69	                        $response->headers->set('X-Cache-Status', 'MISS');
70	                    }
71	
72	                    return $response;
73	                }
74	            }
75	        }
76	
77	        return $response;
78	    }
79	
80	    private function mergeVary(Response $response, array $tokens): void
81	    {
82	        $existing = (string) $response->headers->get('Vary', '');
83	        $varyMap = [];
84	
85	        if ($existing !== '') {
86	            foreach (explode(',', $existing) as $token) {
87	                $trimmed = trim($token);
88	                if ($trimmed !== '') {
89	                    $varyMap[strtolower($trimmed)] = $trimmed;
90	                }
91	            }
92	        }
93	
94	        foreach ($tokens as $token) {
95	            $trimmed = trim($token);
96	            if ($trimmed !== '') {
97	                $varyMap[strtolower($trimmed)] = $trimmed;
98	            }
99	        }
100	
101	        if ($varyMap !== []) {
102	            $response->headers->set('Vary', implode(', ', array_values($varyMap)));
103	        }
104	    }
105	}
